'use strict';

// MODULES //

var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );


// FUNCTIONS //

/**
* Extracts property values from an input object array and assigns results to elements in an output array.
*
* @private
* @param {Array} x - input array
* @param {string} prop - property to access
* @param {Array} out - output array
* @param {integer} stride - stride length for output array
* @param {NonNegativeInteger} offset - starting index for output array
* @returns {Array} output array
*
* @example
* var x = [
*     {
*         'a': 1
*     },
*     {
*         'a': 2
*     },
*     {
*         'a': 3
*     }
* ];
*
* var y = [ 0, 0, 0 ];
* var out = internal( x, 'a', y, 1, 0 );
* // returns [ 1, 2, 3 ]
*
* var bool = ( out === y );
* // returns true
*/
function internal( x, prop, out, stride, offset ) {
	var io;
	var i;
	var v;

	io = offset;
	for ( i = 0; i < x.length; i++ ) {
		v = x[ i ];
		if (
			v !== void 0 &&
			v !== null &&
			hasOwnProp( v, prop )
		) {
			out[ io ] = v[ prop ];
		}
		io += stride;
	}
	return out;
}

/**
* Extracts property values from an input object array and assigns results to elements in an output array.
*
* @private
* @param {Object} x - input array object
* @param {string} prop - property to access
* @param {Object} out - output array object
* @param {integer} stride - stride length for output array
* @param {NonNegativeInteger} offset - starting index for output array
* @returns {Array} output array
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = [
*     {
*         'a': 1
*     },
*     {
*         'a': 2
*     },
*     {
*         'a': 3
*     }
* ];
*
* var y = [ 0, 0, 0 ];
* var out = accessors( arraylike2object( x ), 'a', arraylike2object( y ), 1, 0 );
* // y => [ 1, 2, 3 ]
*/
function accessors( x, prop, out, stride, offset ) {
	var xdata;
	var odata;
	var xget;
	var oset;
	var io;
	var i;
	var v;

	xdata = x.data;
	odata = out.data;

	xget = x.accessors[ 0 ];
	oset = out.accessors[ 1 ];

	io = offset;
	for ( i = 0; i < xdata.length; i++ ) {
		v = xget( xdata, i );
		if (
			v !== void 0 &&
			v !== null &&
			hasOwnProp( v, prop )
		) {
			oset( odata, io, v[ prop ] );
		}
		io += stride;
	}
	return out;
}


// MAIN //

/**
* Extracts property values from an input object array and assigns results to elements in an output array.
*
* @param {Array} x - input array
* @param {string} prop - property to access
* @param {Array} out - output array
* @param {integer} stride - stride length for output array
* @param {NonNegativeInteger} offset - starting index for output array
* @returns {Array} output array
*
* @example
* var x = [
*     {
*         'a': 1
*     },
*     {
*         'a': 2
*     },
*     {
*         'a': 3
*     }
* ];
*
* var out = [ 0, 0, 0 ];
* var y = assign( x, 'a', out, 1, 0 );
* // returns [ 1, 2, 3 ]
*
* var bool = ( out === y );
* // returns true
*/
function assign( x, prop, out, stride, offset ) {
	var ox;
	var oo;

	ox = arraylike2object( x );
	oo = arraylike2object( out );
	if ( ox.accessorProtocol || oo.accessorProtocol ) {
		accessors( ox, prop, oo, stride, offset );
		return out;
	}
	return internal( x, prop, out, stride, offset );
}


// EXPORTS //

module.exports = assign;
